void generateGraph(Graph<V, E> target, Map<String, V> resultMap) {
    // get number of vertices and edges for the target graph from resultMap
    int numVertices = resultMap.size();
    int numEdges = numVertices * (numVertices - 1) / 2;

    // create a complete bipartite graph with the given number of vertices and edges
    for (int i = 0; i < numVertices; ++i) {
        target.addVertex(i, new Vertex("source"));
    }

    for (int i = 0; i < numEdges; ++i) {
        target.addEdge(i, i % numVertices, (i + 1) % numVertices, new Edge("destination"));
    }
}

public void generateGraph(Graph<V,E> target, Map<String,V> resultMap) {

	// Initialize variables
	Set<String> domains = resultMap.keySet();
	int n = domains.size();
	target.addVertices(n);
	target.addEdges(n * (n - 1) / 2);

	// Connect the vertices
	Iterator<String> domainIterator = domains.iterator();
	while (domainIterator.hasNext()) {
		String domain = domainIterator.next();
		V domainVertex = target.getVertex(resultMap.get(domain));
		for (String otherDomain : resultsMap.keySet()) {
			if (!domain.equals(otherDomain)) {
				target.addEdge(domainVertex, target.getVertex(resultMap.get(otherDomain)));
				if (areConnected(domain, otherDomain)) {
					target.setEdgeWeight(domainVertex, target.getVertex(resultMap.get(otherDomain)), 1.0);
				}
			}
		}
	}
}

public void generateGraph(Graph<V,E> target,Map<String,V> resultMap) {
int poolSize = target.vertexSet().size();
int numPartitions = resultMap.size();

// create a pool of "aliases" of each vertex in the graph
ArrayList<V> partitionAliases = new ArrayList<V>(poolSize);
for (V vertex : target.vertexSet()) {
    partitionAliases.add(vertex);
}

