private void reload(List<Set<Integer>> bucketsByLabel, List<Integer> labels, int minLabel) {
    // Find the bucket with the minimum label
    int minBucketIndex = 0;
    for (int i = 0; i < bucketsByLabel.size(); i++) {
        if (labels.get(i) == minLabel) {
            minBucketIndex = i;
            break;
        }
    }

    // Move all vertices from the minimum bucket to the first bucket
    bucketsByLabel.get(0).addAll(bucketsByLabel.get(minBucketIndex));

    // Clear the minimum bucket
    bucketsByLabel.get(minBucketIndex).clear();

    // Update the labels
    for (int i = 0; i < labels.size(); i++) {
        if (labels.get(i) >= minLabel) {
            labels.set(i, labels.get(i) - 1);
