public static String applyRelativePath(String path, String relativePath) {
    if (path == null || relativePath == null) {
        throw new NullPointerException("Path and relative path must not be null");
    }

    if (path.isEmpty() || relativePath.isEmpty()) {
        return path;
    }

    String[] pathParts = path.split(Pattern.quote("/"));
    String[] relativePathParts = relativePath.split(Pattern.quote("/"));

    for (int i = 0; i < relativePathParts.length; i++) {
        if ("..".equals(relativePathParts[i])) {
            if (pathParts.length == 0) {
                throw new IllegalArgumentException("Relative path goes outside of base path");
            }
            pathParts = Arrays.copyOf(pathParts, pathParts.length - 1);
        } else if (!".".equals(relativePathParts[i])) {
            pathParts = Arrays.copyOf(pathParts, pathParts.length + 1);
            pathParts[pathParts.length - 1] = relativePathParts[i];
        }
    }

    return String.join(Path.SEPARATOR, pathParts);
}

