        long currStart = start;
        long currEnd = start + FETCH_DATA_DURATION;
        while (currEnd < end) {
            timeRanges.add(new TimeRange(currStart, currEnd));
            currStart = currEnd + 1;
            currEnd = currStart + FETCH_DATA_DURATION;
        }
        timeRanges.add(new TimeRange(currStart, end));
        return timeRanges;
    }

protected List<TimeRange> buildTimeRanges(long start, long end) {
List<TimeRange> timeRanges = new ArrayList<>();
int duration = (int) (end - start);
for (int i = 0; i < duration; i += FETCH_DATA_DURATION) {
TimeRange timeRange = new TimeRange(start + i, start + i + FETCH_DATA_DURATION < end ? start + i + FETCH_DATA_DURATION : end);
timeRanges.add(timeRange);
}
return timeRanges;
}

protected List<TimeRange> buildTimeRanges(long start, long end)
{
    List<TimeRange> timeRanges = new List<TimeRange>();
    long startOffset = 0L;
    while (startOffset < end - start)
    {
        timeRanges.Add(new TimeRange(start + startOffset, Math.Min(start + startOffset + FETCH_DATA_DURATION, end)));
        startOffset += FETCH_DATA_DURATION;
    }
    return timeRanges;
}

